let a = 5;
let b = 10;

// 利用异或运算（XOR）进行交换
a = a ^ b;
b = a ^ b;
a = a ^ b;

console.log(`a: ${a}, b: ${b}`); // 结果会变成 a: 10, b: 5
```

```javascript
// 定义状态位（每个状态占用二进制中的一位）
const HAS_KEY = 1 << 0;      // 0001 (二进制)
const IS_FIGHTING = 1 << 1;   // 0010 (二进制)
const IS_HIDDEN = 1 << 2;     // 0100 (二进制)

// 初始化角色状态（目前只有钥匙）
let status = HAS_KEY; 

// 1. 给角色增加“战斗中”的状态（按位或运算 |）
status |= IS_FIGHTING; 

// 2. 检查角色是否有“隐藏”状态（按位与运算 &）
const isHidden = (status & IS_HIDDEN) !== 0;

console.log(`当前状态二进制: ${status.toString(2)}`); 
console.log(`是否隐藏？: ${isHidden}`); // 结果是 false
```
